import dlaqsy = require( './index' );


// TESTS //

// The function returns a string...
{
	const A = new Float64Array( 9 );
	const S = new Float64Array( 3 );
	dlaqsy( 'row-major', 'upper', 3, A, 3, S, 0.0625, 9.0 ); // $ExpectType string
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const A = new Float64Array( 9 );
	const S = new Float64Array( 3 );
	dlaqsy( 5, 'upper', 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( true, 'upper', 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( false, 'upper', 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( null, 'upper', 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( void 0, 'upper', 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( [], 'upper', 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( {}, 'upper', 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( ( x: number ): number => x, 'upper', 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a valid matrix triangle...
{
	const A = new Float64Array( 9 );
	const S = new Float64Array( 3 );
	dlaqsy( 'row-major', 5, 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( 'row-major', true, 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( 'row-major', false, 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( 'row-major', null, 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( 'row-major', void 0, 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( 'row-major', [], 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( 'row-major', {}, 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
	dlaqsy( 'row-major', ( x: number ): number => x, 3, A, 3, S, 0.0625, 9.0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
