// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = new Float64Array( 9 );
	const S = new Float64Array( 3 );
	dlaqsy(); // $ExpectError
	dlaqsy( 'row-major' ); // $ExpectError
	dlaqsy( 'row-major', 'upper' ); // $ExpectError
	dlaqsy( 'row-major', 'upper', 3 ); // $ExpectError
	dlaqsy( 'row-major', 'upper', 3, A ); // $ExpectError
	dlaqsy( 'row-major', 'upper', 3, A, 3 ); // $ExpectError
	dlaqsy( 'row-major', 'upper', 3, A, 3, S ); // $ExpectError
	dlaqsy( 'row-major', 'upper', 3, A, 3, S, 0.0625 ); // $ExpectError
	dlaqsy( 'row-major', 'upper', 3, A, 3, S, 0.0625, 9.0, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a string...
{
	const A = new Float64Array( 9 );
	const S = new Float64Array( 3 );
	dlaqsy.ndarray( 'upper', 3, A, 3, 1, 0, S, 1, 0, 0.0625, 9.0 ); // $ExpectType string
}

